#include <apps/openmw/mwrender/oblivionattachment.hpp>
#include <components/resource/resourcesystem.hpp>
#include <components/resource/scenemanager.hpp>
#include <components/resource/niffilemanager.hpp>
#include <components/nif/niffile.hpp>
#include <components/vfs/manager.hpp>
#include <components/vfs/filesystemarchive.hpp>
#include <osg/MatrixTransform>
#include <iostream>
int main(int argc,char** argv)
{
    if(argc!=2) return 2;
    VFS::Manager vfs;
    vfs.addArchive(std::make_unique<VFS::FileSystemArchive>(argv[1])); vfs.buildIndex();
    Resource::ResourceSystem resources(&vfs,0.,nullptr);
    const VFS::Path::Normalized model("owned-shield.nif");
    const auto file=resources.getNifFileManager()->get(model);
    const auto source=resources.getSceneManager()->getTemplate(model);
    osg::ref_ptr<osg::Group> skeleton=new osg::Group;
    osg::ref_ptr<osg::MatrixTransform> socket=new osg::MatrixTransform;
    socket->setName("Custom Socket"); socket->setMatrix(osg::Matrix::translate(10,0,0));
    skeleton->addChild(socket);
    const auto instance=MWRender::attachOblivionRigidPart(*file,source,*resources.getSceneManager(),*skeleton);
    const auto root=MWRender::findOblivionModelRoot(*file,*instance);
    const auto position=root->getWorldMatrices(skeleton).at(0).getTrans();
    unsigned int record=~0u;
    if(!root->getUserValue("recordIndex",record)||record!=0||root==instance||position!=osg::Vec3(11,2,3)) return 1;
    std::cout<<"actual NIF root="<<root->getName()<<" record="<<record<<" position="<<position.x()<<','<<position.y()<<','<<position.z()<<" distinct_from_wrapper=1\n";
}

