    std::string nativeCarriedWeaponNif(float radius, bool childTarget = false, std::uint16_t collisionFlags = 1,
        bool rotatedRoot = false, bool scabbard = false, std::string_view rootName = "Owned weapon",
        std::string_view parent = {})
    {
        const auto bytes = [](const auto& value) {
            return std::string(reinterpret_cast<const char*>(&value), sizeof(value));
        };
        const auto string = [&](std::string_view value) {
            return bytes(std::uint32_t(value.size())) + std::string(value);
        };
        std::string data = "Gamebryo File Format, Version 20.0.0.5\n";
        data += bytes(std::uint32_t{0x14000005}) + bytes(std::uint8_t{1}) + bytes(std::uint32_t{10})
            + bytes(std::uint32_t((childTarget ? 6 : 5) + (scabbard ? 2 : 0) + !parent.empty()))
            + bytes(std::uint32_t{0}) + std::string(3, '\0');
        data += bytes(std::uint16_t(5 + !parent.empty()));
        for (const auto type : {"NiNode", "bhkCollisionObject", "bhkRigidBody", "bhkSphereShape", "BSXFlags"})
            data += string(type);
        if (!parent.empty()) data += string("NiStringExtraData");
        if (childTarget) data += bytes(std::uint16_t{0});
        for (std::uint16_t i = 0; i < 5; ++i) data += bytes(i);
        if (scabbard) data += bytes(std::uint16_t{0}) + bytes(std::uint16_t{0});
        if (!parent.empty()) data += bytes(std::uint16_t{5});
        data += bytes(std::uint32_t{0}); // No groups.
        // NiNode / NiAVObject / NiObjectNET.
        data += string(rootName) + bytes(std::uint32_t(1 + !parent.empty()))
            + bytes(std::int32_t(childTarget ? 5 : 4));
        if (!parent.empty()) data += bytes(std::int32_t((childTarget ? 6 : 5) + (scabbard ? 2 : 0)));
        data += bytes(std::int32_t{-1})
            + bytes(std::uint16_t{14});
        const std::array<float, 13> rootTransform = rotatedRoot
            ? std::array<float, 13>{1,2,3, 0,1,0,-1,0,0,0,0,1, 1}
            : std::array<float, 13>{1,2,3, 1,0,0,0,1,0,0,0,1, 1};
        for (const float value : rootTransform)
            data += bytes(value);
        data += bytes(std::uint32_t{0}) + bytes(std::int32_t(childTarget ? -1 : 1)); // Properties/collision.
        data += bytes(std::uint32_t(unsigned(childTarget) + unsigned(scabbard)));
        if (scabbard) data += bytes(std::int32_t(childTarget ? 6 : 5));
        if (childTarget) data += bytes(std::int32_t{1});
        data += bytes(std::uint32_t{0}); // Effects.
        if (childTarget)
        {
            data += string("Physical child") + bytes(std::uint32_t{0}) + bytes(std::int32_t{-1})
                + bytes(std::uint16_t{14});
            for (const float value : {3.f,4.f,5.f, 0.f,1.f,0.f,-1.f,0.f,0.f,0.f,0.f,1.f, 1.f})
                data += bytes(value);
            data += bytes(std::uint32_t{0}) + bytes(std::int32_t{2})
                + bytes(std::uint32_t{0}) + bytes(std::uint32_t{0});
        }
        data += bytes(std::int32_t(childTarget ? 1 : 0)) + bytes(collisionFlags)
            + bytes(std::int32_t(childTarget ? 3 : 2));
        // bhkRigidBody: shape, world filter/info, entity info, rigid info.
        data += bytes(std::int32_t(childTarget ? 4 : 3)) + std::string(4, '\0') + std::string(20, '\0')
            + std::string(4, '\0') + std::string(20, '\0');
        for (const float value : {0.f,0.f,0.f,0.f, 0.f,0.f,0.f,1.f, // Translation/XYZW rotation.
                 0.f,0.f,0.f,0.f, 0.f,0.f,0.f,0.f, // Velocities.
                 1.f,0.f,0.f,0.f, 0.f,1.f,0.f,0.f, 0.f,0.f,1.f,0.f, // Padded inertia.
                 0.f,0.f,0.f,0.f, 2.f,0.f,0.f,.5f,.1f,100.f,50.f,.01f})
            data += bytes(value);
        data += bytes(std::uint8_t{1}) + std::string(3, '\0') + std::string(12, '\0')
            + bytes(std::uint32_t{0}) + bytes(std::uint32_t{0}); // Constraints/body flags.
        data += bytes(std::uint32_t{0}) + bytes(radius); // Sphere material/radius.
        data += string("BSX") + bytes(std::uint32_t{2}); // Native Havok-enable metadata.
        if (scabbard)
            for (unsigned part = 0; part < 2; ++part)
            {
                data += string(part ? "Scb:0" : "Scb") + bytes(std::uint32_t{0}) + bytes(std::int32_t{-1})
                    + bytes(std::uint16_t{14});
                for (const float value : {0.f,0.f,0.f, 1.f,0.f,0.f,0.f,1.f,0.f,0.f,0.f,1.f, 1.f})
                    data += bytes(value);
                data += bytes(std::uint32_t{0}) + bytes(std::int32_t{-1}) + bytes(std::uint32_t(part ? 0 : 1));
                if (!part) data += bytes(std::int32_t(childTarget ? 7 : 6));
                data += bytes(std::uint32_t{0});
            }
        if (!parent.empty()) data += string("Prn") + string(parent);
        data += bytes(std::uint32_t{1}) + bytes(std::int32_t{0}); // Root.
        return data;
    }
